import{z as B,x as i,o as e,c as p,q as o,j as n,D as E,d as t,s as l,S as s,b as A}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"执行成本预测","description":"","frontmatter":{"title":"执行成本预测","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/execution-cost-forecast-cap.md","filePath":"quant/execution-cost-forecast-cap.md","lastUpdated":1791063341000}'),d={name:"quant/execution-cost-forecast-cap.md"};function m(h,a,D,c,C,u){const r=i("Mermaid");return e(),p("div",null,[a[2]||(a[2]=o('<h1 id="执行成本预测" tabindex="-1">执行成本预测 <a class="header-anchor" href="#执行成本预测" aria-label="Permalink to &quot;执行成本预测&quot;">​</a></h1><div class="epigraph"><p>事前的成本预测决定该不该交易，事后的缺口只决定做得好不好；两者共用一套冲击模型，回答的却是两个问题。</p><footer>—— 据 Perold, The Implementation Shortfall, Journal of Portfolio Management, 1988；Almgren et al., Risk, 2005 整理</footer></div><p><a href="/quant/portfolio-integration-cap">上一课</a>把通过检验的信号正交化、加权、加约束，交出一组目标毛权重，而解权重时成本多半只是占位符。本课把执行成本作为 alpha 换成净值的<strong>最后折扣</strong>：同一组毛权重按不同成本假设折出的净值可以差出一半；换手越高、市值越小，折扣越大。冲击模型的经验与校准已在<a href="/quant/sqrt-impact">线性与平方根冲击</a>讲过，执行日程的最优解在<a href="/quant/almgren-chriss">Almgren–Chriss 最优执行</a>讲过；本课只做它们与组合层的接口：怎么事前估、怎么接回决策、不确定性怎么改仓位。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组合层最常见的成本错误是把交易成本写成常数基点。常数假设对小单是高估（半价差占大头），对大单是致命低估：冲击随参与率按幂律增长，无上限的成本形状被一条水平线抹平。后果有二：换手被「假装免费」，信号每微变一次就全翻一遍；仓位流向流动性差的名字，因为那里毛 IC 往往最高。两个错误回测里都不可见，实盘里都兑现为缺口。</p><p>时点错配是第二个缺口：把冲击全算在开工那一刻，慢信号被冤枉；假装摊开免费，快信号被高估。成本是「日程的函数」而不是「量的函数」——把冲击模型接进组合层时，必须记住这个变量替换。</p><p><span class="marginnote">ADV 就是日均成交量，参与率 \\(q/\\mathrm{ADV}\\) 是「你的单量占这只股票一天成交量的比例」。参与率 10% 意味着当天市场每成交 10 股就有 1 股是你——价格被你自己的单子推着走，这就是冲击的来源，也是它按参与率而非绝对量计算的原因。</span></p><h3 id="三层成本-三种对策" tabindex="-1">三层成本，三种对策 <a class="header-anchor" href="#三层成本-三种对策" aria-label="Permalink to &quot;三层成本，三种对策&quot;">​</a></h3><p>单位成本至少拆三层：半价差截距 \\(s/2\\)、按参与率的临时冲击 \\(k\\sigma(q/\\mathrm{ADV})^{\\delta}\\)、改写公允价的永久项。价差段靠降频与被动挂单省；冲击段靠摊薄参与率省；永久段省不掉，它决定该不该交易。混在一层就会得出「不如快点付」或「慢慢来便宜」这类只对一段成立的结论。</p><p><span class="marginnote">平方根律下总成本 \\(\\propto q^{3/2}\\)：平均成本随规模上升、边际成本随规模下降，小单被价差截距主导，大单反而「越加越便宜」。按边际成本思考的优化器会在大名字上过度集中——必须配单名与参与率硬上限。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>事前估</strong>：对每笔目标交易 \\(q_i\\) 用三层公式算 \\(\\hat c_i\\)；日程 \\(T_i\\) 由信号半衰期给，衰减快的信号不许用「摊平冲击」的长日程。<strong>接回决策</strong>：判据是边际比较——预期边际 alpha \\(\\gt\\) 边际成本才动。优化器不直接吃 \\(q^{3/2}\\)：优化层用凸惩罚做代理，执行层按日程交付真实缺口，两套口径定期核对。<strong>回写</strong>：实盘成交回报按波动与市值分层回归，更新 \\(k\\) 与 \\(\\delta\\)；回写只改成本参数，不改信号定义——改定义就是新试验。</p><p>成本不确定性进入决策的方式是把 \\(\\hat c\\) 换成保守分位：参数 \\(k\\) 置信区间的上端，或压力情景（价差翻倍、深度减半）下的成本，替代点估计进判据。效果等价于下调预期收益：勉强过零的交易不再做，仓位整体收缩——这是对「成本参数本身是估计」的定价，不是拍脑袋保守。</p><p><span class="marginnote">代个数比较量级：价差 10 个基点的小单，一买一卖大约付 10 bp；换成日波动 2%、参与率 10% 的大单，临时冲击约 \\(2\\%\\times\\sqrt{0.1}\\approx63\\) bp，是价差段的六倍多。同一策略在两类单上的主导成本完全不同，这正是「常数基点」假设失真的样子。</span></p>',14)),(e(),n(s,null,{default:E(()=>[l(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E7%9B%AE%E6%A0%87%E6%AF%9B%E6%9D%83%E9%87%8D%22%5D%20--%3E%20Q%5B%22%E6%AF%8F%E7%AC%94%E4%BA%A4%E6%98%93%E9%87%8F%20q%22%5D%0A%20%20Q%20--%3E%20C%5B%22%E4%B8%89%E5%B1%82%E6%88%90%E6%9C%AC%22%5D%0A%20%20SIG%5B%22%E4%BF%A1%E5%8F%B7%E5%8D%8A%E8%A1%B0%E6%9C%9F%22%5D%20--%3E%20T%5B%22%E6%89%A7%E8%A1%8C%E6%97%A5%E7%A8%8B%20T%22%5D%0A%20%20C%20--%3E%20M%7B%22%E8%BE%B9%E9%99%85%20alpha%20%E8%B6%85%E8%BF%87%E8%BE%B9%E9%99%85%E6%88%90%E6%9C%AC%3F%22%7D%0A%20%20M%20--%3E%7C%E5%90%A6%7C%20SKIP%5B%22%E4%B8%8D%E4%BA%A4%E6%98%93%22%5D%0A%20%20M%20--%3E%7C%E6%98%AF%7C%20SCH%5B%22%E6%8C%89%E6%97%A5%E7%A8%8B%E6%89%A7%E8%A1%8C%22%5D%0A%20%20FIL%5B%22%E6%88%90%E4%BA%A4%E5%9B%9E%E6%8A%A5%22%5D%20--%3E%20CAL%5B%22%E5%88%86%E5%B1%82%E5%9B%9E%E5%BD%92%E6%9B%B4%E6%96%B0%20k%20%E4%B8%8E%20delta%22%5D%0A%20%20CAL%20--%3E%20C%0A%20%20SCH%20--%3E%20NET%5B%22%E5%87%80%E6%9C%9F%E6%9C%9B%E5%87%80%E5%80%BC%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[t("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"成本折扣改变的不只是净值水平，还有组合的形状。平方根的凹边际使成本对规模温和、对换手严酷：翻倍仓位的成本远多于翻倍换手的成本，成本模型天然惩罚「高换手加大集中」。写进优化器后，解自动向低换手、高流动性倾斜——这是 alpha 与成本的正确相对价格。",-1)),(e(),n(s,null,{default:E(()=>[l(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIZE%7B%22%E8%AE%A2%E5%8D%95%E8%A7%84%E6%A8%A1%E5%8F%98%E5%A4%A7%22%7D%0A%20%20SIZE%20--%3E%7C%22%E5%B8%B8%E6%95%B0%E5%81%87%E8%AE%BE%22%7C%20FLAT%5B%22%E6%88%90%E6%9C%AC%E6%98%AF%E4%B8%80%E6%9D%A1%E6%B0%B4%E5%B9%B3%E7%BA%BF%22%5D%0A%20%20FLAT%20--%3E%20BAD%5B%22%E5%A4%A7%E5%8D%95%E8%A2%AB%E5%81%87%E8%A3%85%E5%85%8D%E8%B4%B9%EF%BC%8C%E9%AB%98%E6%8D%A2%E6%89%8B%E4%B8%8D%E5%8F%97%E7%BD%9A%22%5D%0A%20%20BAD%20--%3E%20DISTORT%5B%22%E4%BB%93%E4%BD%8D%E6%B5%81%E5%90%91%E5%B7%AE%E6%B5%81%E5%8A%A8%E6%80%A7%E3%80%81%E6%8D%A2%E6%89%8B%E5%A4%B1%E6%8E%A7%22%5D%0A%20%20SIZE%20--%3E%7C%22%E5%B9%B3%E6%96%B9%E6%A0%B9%E5%B9%82%E5%BE%8B%22%7C%20POW%5B%22%E6%88%90%E6%9C%AC%E9%9A%8F%E8%A7%84%E6%A8%A1%E5%8A%A0%E9%80%9F%E4%B8%8A%E5%8D%87%22%5D%0A%20%20POW%20--%3E%20REAL%5B%22%E5%A4%A7%E5%8D%95%E4%B8%8E%E9%AB%98%E6%8D%A2%E6%89%8B%E8%A2%AB%E7%9C%9F%E5%AE%9E%E8%AE%A1%E4%BB%B7%22%5D%0A%20%20REAL%20--%3E%20TILT%5B%22%E8%A7%A3%E8%87%AA%E5%8A%A8%E5%80%BE%E5%90%91%E4%BD%8E%E6%8D%A2%E6%89%8B%E3%80%81%E9%AB%98%E6%B5%81%E5%8A%A8%E6%80%A7%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p>不确定性的机制要点在凸性：估计误差平均下来总是多付而非少付，保守分位近似正确方向的修正。反过来，用乐观成本做回测再拿实盘「验证」，缺口就是模型误差与运气混在一起的残渣，事后无法归因。</p><p><span class="marginnote">初学者容易觉得「用保守分位是胆子太小」。机制上这是凸性修正：参数估错时，多付的损失比省下的收益更大，误差平均下来总是净亏。把成本换成高分位，等价于给预期收益打折——勉强过零的交易自动出局，这是在给「参数本身也是估计」定价。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>校准域外不外推：涨跌停使 \\(q\\) 不可执行而非更贵，危机与拥挤使 ADV 分母失真，这两类日子应把可执行集当硬约束而不是放大 \\(k\\)。预测与归因分工：本课的模型回答事前，成交后的缺口归因回答事后，两者必须同一到达价、同一分层。成本预测给的是期望与分位，不是保证：回答「该不该交易、以什么节奏」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>执行成本是 alpha 换净值的最后折扣：换手越高、市值越小，折扣占比越大。</li><li>常数基点成本对小单高估、对大单低估，会同时制造过度换手与向差流动性集中。</li><li>成本拆价差、临时、永久三层，分别对应降频、摊薄参与率、判断该不该交易。</li><li>优化层用凸代理、执行层按日程交付，判据是边际 alpha 对边际成本。</li><li>成本不确定性用保守分位进决策，等价于下调预期收益、收缩仓位。</li><li>出处：Perold, <em>JPM</em>, 1988；Almgren, Thum, Hauptmann and Li, <em>Risk</em>, 2005；模型细节见<a href="/quant/sqrt-impact">线性与平方根冲击</a>与<a href="/quant/almgren-chriss">Almgren–Chriss 最优执行</a>。</li></ul>',6))])}const _=B(d,[["render",m]]);export{q as __pageData,_ as default};
